import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易要义卷二 * 上","description":"周易要义 - 周易要义卷二 * 上","frontmatter":{"title":"周易要义卷二 * 上","description":"周易要义 - 周易要义卷二 * 上"},"headers":[],"relativePath":"zh/classics/yaoyi/005.md","filePath":"zh/classics/yaoyi/005.md"}'),r={name:"zh/classics/yaoyi/005.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易要义卷二-上" tabindex="-1">周易要义卷二 * 上 <a class="header-anchor" href="#周易要义卷二-上" aria-label="Permalink to “周易要义卷二 * 上”">​</a></h1><p>钦定四库全书</p><p>宋魏了翁辑泰至谦</p><p>䷊</p><p>乾下坤上 泰：小往大来，吉，亨。正义曰：「小往大来，吉亨」者，阴去故「小往」，阳长故「大来」，以此吉而亨通。此卦亨通之极，而四德不具者，物既泰通，多失其节，故不得以为元始而利贞也。所以象云「财成辅相」，故四德不具。泰，如字。大通也，郑云：「通也。」马云：「大也。」坤宫三世卦</p><p>象曰：天地交，泰。后以财成天地之道，辅相天地之宜，以左右民。「泰」者，物大通之时也。上下大通，则物失其节，故财成而辅相，以左右民也。「天地之道」者，谓四时也。冬寒夏暑、春生秋杀之道，若气相交通，则物失其节。物失其节，则冬温夏寒，秋生春杀。君当财节成就，使寒暑得其常，生杀依其节。此天地自然之气，故云「天地之道」也。「天地之宜」者，谓天地所生之物，各有其宜。若大司徒云「其动物植物」，及职方云扬州其贡宜稻麦，雍州其贡宜黍稷。若天气大同，则所宜相反，故人君辅助天地所宜之物，各安其性，得其宜。</p><p>九三，无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。乾本上也，坤本下也，而得泰者，降与升也。而三处天地之际，将复其所处。复其所处，则上守其尊，下守其卑，是故无往而不复也，无平而不陂也。处天地之将闭，平路之将陂，时将大变，世将大草，而居不失其正，动不失其应，艰而能贞，不失其义，故「无咎」也。信义诚著，故不恤其孚而自明也，故曰「勿恤其孚，于食有福」也。陂，彼伪反，徐甫寄反，倾也，注同；又破河反，偏也。象曰：「无往不复」，天地际也。天地将各分复之际，</p><p>六四，翩翩，不富以其邻，不戒以孚。乾乐上复，坤乐下复，四处坤首，不固所居，见命则退，故曰「翩翩」也。坤爻皆乐下，己退则从，故不待富而用其邻也。莫不与己同其志愿，故不待戒而自孚也。象曰：「翩翩不富」，皆失实也。「不戒以孚」，中心愿也。正义曰：「六四，翩翩」者，四主坤首，而欲下复，见命则退，故翩翩而下。象曰「皆失实」者，解「翩翩不富」之义。由众阴皆失其本实所居之处，今既见命，翩翩乐动，不待财富，并悉从之，故云「皆失实」也。「不戒以孚，中心愿」者，解「不戒以孚」之义。所以不待六四之戒告，而六五、上六皆已孚信者，由中心皆愿下复，故不待戒而自孚也。</p><p>六五，帝乙归妹，以祉元吉。妇人谓嫁曰「归」。泰者，阴阳交通之时也。女处尊位，履中居顺，降身应二，感以相与，用中行愿，不失其礼。「帝乙归妹」，诚合斯义。履顺居中，行愿以祉，尽夫阴阳交配之宜，故「元吉」也。祉，音耻，一音𠡠子反，又音止。</p><p>上六，城复于隍，勿用师。自邑告命，贞吝。居泰上极，各反所应。泰道将灭，上下不交，卑不上承，尊不下施，是故「城复于隍」，卑道崩也。「勿用师」，不烦攻也。「自邑告命，贞吝」，否道已成，命不行也。隍，音皇，城堑也。子夏作「堭」，姚作「湟」。正义曰：子夏传云：隍是城下池也。城之为体，由基土培扶，乃得为城。今下不培扶，则损坏，以此崩倒，反复于隍。犹君之为体，由臣之辅翼。今上下不交，臣不扶君，君道倾危。</p><p>䷋</p><p>坤下乾上 否之匪人，不利君子贞，大往小来。疏：「否之」至「小来」。正义曰：「否之匪人」者，言否闭之世，非是人道交通之时，故云「匪人」。不利君子贞者，由小人道长，君子道消，故不利君子为正也。阳气往而阴气来，故云「大往小来」。阳主生息，故称大。阴主消耗，故称小。否，备鄙反，卦内同，闭也，塞也。乾宫三世卦</p><p>初六，拔茅茹以其汇，贞吉，亨。居否之初，处顺之始，为类之首者也。顺非健也，何可以征？居否之时，动则入邪，三阴同道，皆不可进，故「茅茹」以类，贞而不谄，则「吉亨」。邪，似嗟反。谄，𠡠检反。象曰：「拔茅贞吉」，志在君也。志在于君，故不苟进。</p><p>六二，「包承」至乱群也。正义曰：「包承」者，居否之世而得其位，用其至顺，包承于上。「小人吉」者，否闭之时，小人路通，故于小人为吉也。「大人否，亨」者，若大人用此包承之德，能否闭小人之吉，其道乃「亨」。象曰「大人否，亨，不乱群」者，此释所以「大人否，亨」之意。良由否闭小人，防之以得其道，小人虽盛，不敢乱群。</p><p>䷌</p><p>离下乾上 同人于野，亨。利涉大川，利君子贞。正义曰：同人谓和同于人。「于野，亨」者，野是广远之处，借其野名，喻其广远。言和同于人，必须宽广，无所不同，用心无私，处非近狭，远至于野，乃得亨通，故云「同人于野，亨」。与人同心，足以涉难，故曰「利涉大川」也。与人和同，易涉邪僻，故「利君子贞」也。此「利涉大川」，假物象以明人事。同人，和同也。离宫归魂卦</p><p>同人。曰「同人于野，亨，利涉大川，乾行也」。所以乃得「同人于野，亨，利涉大川」，非二之所能也，是乾之所行，故特曰「同人曰」。</p><p>象曰：「天与」至「辨物」。正义曰：天体在上，火又炎上，取其性同，故云「天与火」。同人。「君子以类族辨物」者，族，聚者也。言君子法此「同人」，以类而聚也。「辨物」谓分辨事物，各同其党，使自相同，不间杂也。辨如字，王肃卜免反。</p><p>初九，「同人于门」至谁咎也。正义曰：「同人于门」者，居同人之首，无应于上，心无系吝，含弘光大，和同于人，在于门外，出门皆同，故云「无咎」也。象曰「又谁咎」者，释「出门同人无咎」之义。言既心无系吝，出门逢人皆同，则谁与为过咎。</p><p>上九，同人于郊，无悔。郊者，外之极也。处「同人」之时，最在于外，不𫉬同志，而远于内争，故虽无悔吝，亦未得其志。远，袁万反。争，争斗之争。象曰：「同人于郊」，志未得也。凡处同人而不泰焉，则必用师矣。不能大通，则各私其党而求利焉。楚人亡弓，不能忘楚，爱国愈甚，益为他灾，是以同人不弘。刚健之爻，皆至用师也。正义曰：「凡处同人而不泰焉，则必用师矣」者，王氏注意非止上九一爻，乃总论同人一卦之义。去初、上而言，二有同宗之吝，三有「伏戎」之祸，四有不克之困，五有「大师」之患，是处「同人」之世，无大通之志，则必用师矣。「楚人亡弓，不能忘楚，爱国愈甚，益为他灾」者，案：孔子家语弟子好生篇云：「楚昭王出游，亡乌号之弓。左右请求之。王曰：楚人亡弓，楚人得之，又何求焉？孔子闻之曰：惜乎，其志不大也。不曰人亡弓，人得之，何必楚也？」昭王名轸。哀六年，吴伐陈，楚救陈，在城父卒。此爱国而致他灾也。引此者，证同人不弘皆至用师矣。</p><p>䷍</p><p>乾下离上 大有：元亨。不大通，何由得「大有」乎？「大有」则必元亨矣。正义曰：「大有，元亨」者，柔得尊位，群阳并应，能大所有，故称「大有」。既能「大有」，则其物大得亨通，故云「大有，元亨」。大有，包容丰富之象。乾宫归魂卦</p><p>象曰：火在天上，「大有」。君子以遏恶扬善，顺天休命。大有，包容之象，故遏恶扬善，成物之性。「顺天休命」，顺物之命。正义曰：不云天在火下而云「火在天上」者，天体高明，火性炎上，是照耀之物，而在于天上，是光明之甚，无所不照，亦是包含之义，又为扬善之理也。</p><p>九三公用亨于天子小人弗克处大有之时居下体之极，乘刚健之上，而履得其位，与五同功，威权之盛，莫此过焉。公用斯位，乃得通乎天子之道也。小人不克，害可待也。亨，许庚反，通也。下同。众家并香两反。京云：「献也。」于云：「享宴也。」姚云：「享，祀也。」</p><p>九四：「匪其彭，无咎。」既失其位，而上近至尊之威，下比分权之臣，其为惧也可谓危矣。惟夫有圣知者，乃能免斯咎也。三虽至盛，五不可舍，能辨斯数，专心承五，常匪其旁，则「无咎」矣。旁，谓三也。彭，步郎反，子夏传作「旁」。于云：「彭亨，骄满貌。」王肃云：「壮也。」虞作𡯁。姚云：「彭、旁，俗音同。」</p><p>䷎</p><p>艮下坤上 「谦」：亨，君子有终。正义曰：「谦」者，屈躬下物，先人后己，以此待物，则所在皆通，故曰「亨」也。小人行谦，则不能长久，唯「君子有终」也。谦必获吉，其吉可知，故不言之。凡易经之体，有吉理可知而不言「吉」者，即此谦卦之繇，及乾之九五「利见大人」，是吉理分明，故不云「吉」也。若坤之六五及泰之六五，并以阴居尊位，若不行此事则无吉，若行此事则得其吉，故并称「元吉」。其余皆言「吉事」，亦仿此。亦有大人为吉，于小人为凶，若否之九五云「休否，大人吉」是也。或有于小人为吉，大人为凶，若屯之九五「小贞吉，大贞凶」及否之六二「包承，小人吉」之类是也。亦有其吉灼然而称「吉」者，若大有上九「自天祐之，吉，无不利」之类是也。但易之为体，不可以一为例，今各随文解之，义具诸卦之下。今谦卦之繇，其吉可知也。既不云「吉」，何故初六、六二及九三并云「吉」者？谦卦是总诸六爻，其善既大，故不须云「吉」也。六爻各明其义，其义有优劣，其德既小，嫌其不吉，故须「吉」以明之也。谦卑退为义，屈己下物也。兑宫五世卦，子夏作「衔」，云：衔，谦也。</p><p>彖曰：「谦亨」至之终也正义曰：「谦，亨。天道下济而光明，地道卑而上行」者，此释「亨」义也。欲明天地上下交通，「坤」体在上，故言「地道卑而上行」也。其地道既上行，天地相对，则「天道下济」也。且「艮」为阳卦，又为山，天之高明，今在下体，亦是「天道下济」之义也。「下济」者，谓降下济生万物也。而「光明」者，谓三光垂耀而显明也。「地道卑而上行」者，地体卑柔而气上行，交通于天，以生万物也。「天道亏盈而益谦」者，从此以下，广说谦德之美，以结君子能终之义也。「亏」谓减损，减损盈满而增益谦退。若日中则昃，月盈则食，是亏减其盈。盈者亏减，则谦者受益也。「地道变盈而流谦」者，丘陵川谷之属，高者渐下，下者益高，是改变「盈」者，流布「谦」者也。「鬼神害盈而福谦」者，骄盈者被害，谦退者受福，是「害盈而福谦」也。「人道恶盈而好谦」者，盈溢骄慢者皆以恶之，谦退恭巽悉皆好之。「谦尊而光，卑而不可逾」者，尊者有谦而更光明盛大，卑谦而不可逾越，是君子之所终也。言君子能终其谦之善事，又𫉬谦之终福，故云「君子之终」也。</p><p>象曰：地中有山，谦。君子以裒多益寡，称物平施。多者用谦以为裒，少者用谦以为益，随物而与，施不失平也。正义曰：「裒多」者，君子若能用此谦道，则裒益其多。言多者得谦，物更裒聚，弥益多也，故云「裒多」即谦尊而光也，是尊者得谦而光大也。「益寡」者，谓寡者得谦而更进益，即卑而不可逾也，是卑者得谦而更增益，不可逾越也。「称物平施」者，称此物之多少，均平而施。</p><p>上六，鸣谦，利用行师，征邑国。最处于外，不与内政，故有鸣而已，志功未得也。处外而履谦顺，可以「征邑国」而已。征邑国，本或作「征国邑」者，非。象曰：「鸣谦」，志未得也。可用行师，「征邑国」也。夫吉凶悔吝，生乎动者也。动之所起，兴于利者也。故饮食必有讼，讼必有众起。未有居众人之所恶，而为动者所害；处不竞之地而为争者所夺。是以六爻虽有失位、无应、乘刚，而皆无凶咎悔吝者，以谦为主也。「谦尊而光，卑而不可逾」，信矣哉！周易要义卷二上，</p>',30)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
